// Operator-approved custom scrapers (generated by the AI Scraper Builder).
// A scraper is a CommonJS module exporting { id, description?, discover(ctx) }
// that returns SearchHit[]. Generated code is:
//   1. smoke-tested in a separate node child process (memory-capped, timed,
//      minimal env) with the code executed inside a node:vm context that
//      exposes only safe globals — no require/process/fs;
//   2. stored in DATA_DIR/custom-sources/<id>.js only after the operator
//      reviews the code and approves registration;
//   3. re-executed inside a vm context at run time (operator-approved code,
//      same restricted globals).

import * as fs from "node:fs";
import * as path from "node:path";
import * as vm from "node:vm";
import type { DiscoverCtx, SearchHit } from "./types.js";

export interface CustomSource {
  id: string;
  description: string;
  code: string;
  createdAt: string;
  discover: (ctx: DiscoverCtx) => Promise<SearchHit[]>;
}

const registry = new Map<string, CustomSource>();
const ID_RE = /^[a-z0-9][a-z0-9-]{1,40}$/;
const MAX_CODE_BYTES = 50_000;

function customSourcesDir(dataDir: string): string {
  return path.join(dataDir, "custom-sources");
}

function sandboxGlobals(extra: Record<string, unknown>): Record<string, unknown> {
  return {
    console: {
      log: (...a: unknown[]) => console.log("[scraper]", ...a),
      error: (...a: unknown[]) => console.error("[scraper]", ...a),
    },
    fetch,
    URL,
    AbortSignal,
    TextDecoder,
    TextEncoder,
    setTimeout: (fn: () => void, ms?: number) => setTimeout(fn, Math.min(ms ?? 0, 5_000)),
    clearTimeout,
    require: () => {
      throw new Error("require() is not available in scrapers");
    },
    ...extra,
  };
}

/** Compile a module in a fresh vm context and return its exports. */
function compileModule(code: string): { id?: unknown; description?: unknown; discover?: unknown } {
  const mod = { exports: {} as Record<string, unknown> };
  const context = vm.createContext(sandboxGlobals({ module: mod, exports: mod.exports }));
  new vm.Script(code, { filename: "scraper.js" }).runInContext(context, { timeout: 5_000 });
  return mod.exports as { id?: unknown; description?: unknown; discover?: unknown };
}

export function validateScraperCode(code: string, expectedId?: string): { ok: true; id: string; description: string } | { ok: false; error: string } {
  if (!code || code.length > MAX_CODE_BYTES) {
    return { ok: false, error: `code must be 1-${MAX_CODE_BYTES} chars` };
  }
  let exports: { id?: unknown; description?: unknown; discover?: unknown };
  try {
    exports = compileModule(code);
  } catch (e) {
    return { ok: false, error: `compile failed: ${e instanceof Error ? e.message : String(e)}` };
  }
  const id = typeof exports.id === "string" ? exports.id : expectedId ?? "";
  if (!ID_RE.test(id)) {
    return { ok: false, error: `invalid or missing id (expected kebab-case, e.g. "my-source")` };
  }
  if (expectedId && id !== expectedId) {
    return { ok: false, error: `module id "${id}" does not match "${expectedId}"` };
  }
  if (typeof exports.discover !== "function") {
    return { ok: false, error: "module must export a discover(ctx) function" };
  }
  return { ok: true, id, description: typeof exports.description === "string" ? exports.description : "" };
}

function makeSource(id: string, description: string, code: string, createdAt: string): CustomSource {
  return {
    id,
    description,
    code,
    createdAt,
    discover: async (ctx: DiscoverCtx): Promise<SearchHit[]> => {
      const exports = compileModule(code);
      const result = await (exports.discover as (c: DiscoverCtx) => Promise<SearchHit[]>)(ctx);
      if (!Array.isArray(result)) return [];
      return result
        .filter((h) => h && typeof h.url === "string" && typeof h.title === "string")
        .map((h) => ({ url: h.url, title: h.title, description: typeof h.description === "string" ? h.description : "", name: h.name }));
    },
  };
}

export function registerCustomSource(dataDir: string, id: string, description: string, code: string): { ok: true; source: CustomSource } | { ok: false; error: string } {
  const check = validateScraperCode(code, id);
  if (!check.ok) return check;
  const dir = customSourcesDir(dataDir);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, `${id}.js`), code, "utf8");
  const source = makeSource(id, description, code, new Date().toISOString());
  registry.set(id, source);
  return { ok: true, source };
}

export function unregisterCustomSource(dataDir: string, id: string): boolean {
  if (!registry.delete(id)) return false;
  try {
    fs.unlinkSync(path.join(customSourcesDir(dataDir), `${id}.js`));
  } catch {
    /* already gone */
  }
  return true;
}

/** Load DATA_DIR/custom-sources/*.js at boot (operator-approved files). */
export function loadCustomSources(dataDir: string): string[] {
  const dir = customSourcesDir(dataDir);
  if (!fs.existsSync(dir)) return [];
  const loaded: string[] = [];
  for (const f of fs.readdirSync(dir)) {
    if (!f.endsWith(".js")) continue;
    const id = f.slice(0, -3);
    if (!ID_RE.test(id)) continue;
    try {
      const code = fs.readFileSync(path.join(dir, f), "utf8");
      const check = validateScraperCode(code, id);
      if (!check.ok) {
        console.warn(`[custom-sources] skipping ${f}: ${check.error}`);
        continue;
      }
      registry.set(id, makeSource(id, check.description, code, new Date().toISOString()));
      loaded.push(id);
    } catch (e) {
      console.warn(`[custom-sources] skipping ${f}: ${e instanceof Error ? e.message : String(e)}`);
    }
  }
  return loaded;
}

export function getCustomSource(id: string): CustomSource | null {
  return registry.get(id) ?? null;
}

export function listCustomSources(): Array<{ id: string; description: string; createdAt: string }> {
  return [...registry.values()]
    .map((s) => ({ id: s.id, description: s.description, createdAt: s.createdAt }))
    .sort((a, b) => (a.id < b.id ? -1 : 1));
}

/** True when a vertical's source id is a registered custom scraper. */
export function isCustomSource(id: string): boolean {
  return registry.has(id);
}
